input.command:
cat > ci.tf <<'EOF'
# AWS side of the CI handover: GitHub Actions in platform/ingest authenticates via OIDC
# (no long-lived keys) and assumes one of two roles:
#   - plan  : pull_request runs, read-only on managed resources
#   - apply : runs on the main branch only, scoped to this configuration's resources

locals {
  github_repo = "platform/ingest"

  state_bucket = "ingest-terraform-state"
  state_key    = "ingest/terraform.tfstate"

  managed_bucket_arn = aws_s3_bucket.landing.arn
  managed_queue_arn  = aws_sqs_queue.events.arn
  managed_table_arn  = aws_dynamodb_table.checkpoints.arn
}

resource "aws_iam_openid_connect_provider" "github" {
  url            = "https://token.actions.githubusercontent.com"
  client_id_list = ["sts.amazonaws.com"]
  # AWS validates GitHub's certificate via its trusted CA library; thumbprint is not used.
}

data "aws_iam_policy_document" "trust_apply" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }
    # Exact match: only the main branch of this repository (not forks, PRs, or other branches).
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${local.github_repo}:ref:refs/heads/main"]
    }
  }
}

data "aws_iam_policy_document" "trust_plan" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${local.github_repo}:pull_request"]
    }
  }
}

# Remote state access (S3 backend with use_lockfile).
data "aws_iam_policy_document" "state_rw" {
  statement {
    actions   = ["s3:ListBucket"]
    resources = ["arn:aws:s3:::${local.state_bucket}"]
    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values   = ["${local.state_key}", "${local.state_key}.tflock"]
    }
  }
  statement {
    actions = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = [
      "arn:aws:s3:::${local.state_bucket}/${local.state_key}",
      "arn:aws:s3:::${local.state_bucket}/${local.state_key}.tflock",
    ]
  }
}

data "aws_iam_policy_document" "state_lock_only" {
  statement {
    actions   = ["s3:ListBucket"]
    resources = ["arn:aws:s3:::${local.state_bucket}"]
    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values   = ["${local.state_key}", "${local.state_key}.tflock"]
    }
  }
  statement {
    actions   = ["s3:GetObject"]
    resources = ["arn:aws:s3:::${local.state_bucket}/${local.state_key}"]
  }
  # plan takes the lockfile; it cannot modify state itself.
  statement {
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = ["arn:aws:s3:::${local.state_bucket}/${local.state_key}.tflock"]
  }
}

data "aws_iam_policy_document" "read_managed" {
  statement {
    actions   = ["s3:Get*", "s3:ListBucket"]
    resources = [local.managed_bucket_arn]
  }
  statement {
    actions   = ["sqs:GetQueueAttributes", "sqs:ListQueueTags"]
    resources = [local.managed_queue_arn]
  }
  statement {
    actions = [
      "dynamodb:DescribeTable",
      "dynamodb:DescribeContinuousBackups",
      "dynamodb:DescribeTimeToLive",
      "dynamodb:ListTagsOfResource",
    ]
    resources = [local.managed_table_arn]
  }
}

data "aws_iam_policy_document" "manage_managed" {
  statement {
    actions   = ["s3:*"]
    resources = [local.managed_bucket_arn, "${local.managed_bucket_arn}/*"]
  }
  statement {
    actions   = ["sqs:*"]
    resources = [local.managed_queue_arn]
  }
  statement {
    actions   = ["dynamodb:*"]
    resources = [local.managed_table_arn, "${local.managed_table_arn}/*"]
  }
}

resource "aws_iam_role" "ci_apply" {
  name                 = "ingest-ci-apply"
  assume_role_policy   = data.aws_iam_policy_document.trust_apply.json
  max_session_duration = 3600
}

resource "aws_iam_role_policy" "ci_apply_state" {
  name   = "terraform-state"
  role   = aws_iam_role.ci_apply.id
  policy = data.aws_iam_policy_document.state_rw.json
}

resource "aws_iam_role_policy" "ci_apply_manage" {
  name   = "manage-ingest-resources"
  role   = aws_iam_role.ci_apply.id
  policy = data.aws_iam_policy_document.manage_managed.json
}

resource "aws_iam_role" "ci_plan" {
  name                 = "ingest-ci-plan"
  assume_role_policy   = data.aws_iam_policy_document.trust_plan.json
  max_session_duration = 3600
}

resource "aws_iam_role_policy" "ci_plan_state" {
  name   = "terraform-state"
  role   = aws_iam_role.ci_plan.id
  policy = data.aws_iam_policy_document.state_lock_only.json
}

resource "aws_iam_role_policy" "ci_plan_read" {
  name   = "read-ingest-resources"
  role   = aws_iam_role.ci_plan.id
  policy = data.aws_iam_policy_document.read_managed.json
}

output "ci_apply_role_arn" {
  value = aws_iam_role.ci_apply.arn
}

output "ci_plan_role_arn" {
  value = aws_iam_role.ci_plan.arn
}
EOF
terraform fmt -check ci.tf; terraform init -backend=false >/dev/null 2>&1 && terraform validate 2>&1 | tail -5

